/*
 * Generated by OpenAI Codex for ZZZ-OS on 2026-09-16.
 *
 * This read-only benchmark has two parts:
 *   1. warmed raw block reads, measuring the BIO and block-driver path;
 *   2. cold/hot file reads, measuring Ext2 and page-cache behaviour.
 */

#include <fs/blkdev.h>
#include <fs/file.h>
#include "blk_read_bench.h"
#include <os/err.h>
#include <os/errno.h>
#include <os/init.h>
#include <os/kmalloc.h>
#include <os/printk.h>
#include <os/timekeeping.h>
#include <os/utils.h>

#define BLK_BENCH_DEVICE        "vda"
#define BLK_BENCH_TOTAL_BYTES   (2U * 1024U * 1024U)
#define BLK_BENCH_ROUNDS        3U
#define FILE_BENCH_PATH         "/bin/ls"
#define FILE_BENCH_BUFFER_SIZE  (64U * 1024U)
#define FILE_BENCH_HOT_ROUNDS   3U

static int blk_read_pass(struct blkdev *bdev, void *buffer,
                         size_t request_size, size_t total_bytes,
                         u64 *elapsed_ns_out)
{
    size_t completed = 0;
    u64 start_ns;
    int ret;

    start_ns = monotonic_ns();
    while (completed < total_bytes) {
        size_t len = request_size;

        if (len > total_bytes - completed)
            len = total_bytes - completed;

        ret = blkdev_read(bdev, buffer, len, completed);
        if (ret < 0)
            return ret;

        completed += len;
    }

    if (elapsed_ns_out)
        *elapsed_ns_out = monotonic_ns() - start_ns;
    return 0;
}

int blk_read_bench_run(const char *device_name, size_t request_size,
                       size_t total_bytes)
{
    struct blkdev *bdev;
    void *buffer;
    u64 device_bytes;
    u64 total_elapsed_ns = 0;
    u64 min_elapsed_ns = (u64)-1;
    u64 max_elapsed_ns = 0;
    u64 elapsed_ns;
    u64 requests;
    u64 kib_per_sec;
    u64 iops;
    size_t npages;
    int ret = 0;

    if (!device_name || request_size == 0 || total_bytes == 0)
        return -EINVAL;

    bdev = blkdev_get_by_path(device_name);
    if (IS_ERR(bdev))
        return PTR_ERR(bdev);

    if (!bdev->bd_disk || !bdev->bd_disk->queue) {
        ret = -ENODEV;
        goto out_put;
    }

    if (request_size % bdev->bd_disk->queue->logical_block_size != 0) {
        ret = -EINVAL;
        goto out_put;
    }

    device_bytes = (u64)bdev->bd_nr_sectors * SECTOR_SIZE;
    if (request_size > device_bytes) {
        ret = -EINVAL;
        goto out_put;
    }

    if (total_bytes > device_bytes)
        total_bytes = device_bytes;
    total_bytes -= total_bytes % request_size;
    if (total_bytes == 0) {
        ret = -EINVAL;
        goto out_put;
    }

    npages = (request_size + PAGE_SIZE - 1) / PAGE_SIZE;
    buffer = page_alloc(npages);
    if (!buffer) {
        ret = -ENOMEM;
        goto out_put;
    }

    /* Warm the complete range so every request size sees the same cache state. */
    ret = blk_read_pass(bdev, buffer, request_size, total_bytes, NULL);
    if (ret < 0)
        goto out_free;

    for (u32 round = 0; round < BLK_BENCH_ROUNDS; round++) {
        ret = blk_read_pass(bdev, buffer, request_size, total_bytes,
                            &elapsed_ns);
        if (ret < 0)
            break;

        total_elapsed_ns += elapsed_ns;
        if (elapsed_ns < min_elapsed_ns)
            min_elapsed_ns = elapsed_ns;
        if (elapsed_ns > max_elapsed_ns)
            max_elapsed_ns = elapsed_ns;
    }

    if (ret == 0) {
        requests = (total_bytes / request_size) * BLK_BENCH_ROUNDS;
        if (total_elapsed_ns == 0)
            total_elapsed_ns = 1;
        kib_per_sec = (u64)total_bytes * BLK_BENCH_ROUNDS * NSEC_PER_SEC;
        kib_per_sec /= total_elapsed_ns;
        kib_per_sec /= 1024ULL;
        iops = requests * NSEC_PER_SEC / total_elapsed_ns;

        printk("blk-read-bench: raw request=%lu rounds=%u bytes_per_round=%lu "
               "avg_us=%lu min_us=%lu max_us=%lu "
               "avg_KiB_s=%lu avg_iops=%lu\n",
               (unsigned long)request_size, BLK_BENCH_ROUNDS,
               (unsigned long)total_bytes,
               (unsigned long)(total_elapsed_ns / BLK_BENCH_ROUNDS / 1000ULL),
               (unsigned long)(min_elapsed_ns / 1000ULL),
               (unsigned long)(max_elapsed_ns / 1000ULL),
               (unsigned long)kib_per_sec,
               (unsigned long)iops);
    }

out_free:
    page_free(buffer);
out_put:
    blkdev_put(bdev);
    return ret;
}

static int file_read_pass(struct file *file, void *buffer, size_t buffer_size,
                          u64 *bytes_out, u64 *elapsed_ns_out)
{
    loff_t pos = 0;
    u64 bytes = 0;
    u64 start_ns;

    start_ns = monotonic_ns();
    while ((size_t)pos < file->f_inode->i_size) {
        size_t len = file->f_inode->i_size - (size_t)pos;
        ssize_t ret;

        if (len > buffer_size)
            len = buffer_size;

        ret = kernel_read_at(file, pos, buffer, len);
        if (ret < 0)
            return (int)ret;
        if (ret == 0)
            break;

        pos += ret;
        bytes += ret;
    }

    *bytes_out = bytes;
    *elapsed_ns_out = monotonic_ns() - start_ns;
    return 0;
}

static void file_read_bench(void)
{
    static const size_t hot_request_sizes[] = {
        SECTOR_SIZE,
        PAGE_SIZE,
        FILE_BENCH_BUFFER_SIZE,
    };
    struct file *file;
    void *buffer;
    u64 open_start_ns;
    u64 open_elapsed_ns;
    u64 cold_elapsed_ns;
    u64 bytes;
    u64 kib_per_sec;
    size_t npages;
    int ret;

    open_start_ns = monotonic_ns();
    file = filp_open(FILE_BENCH_PATH, O_RDONLY);
    open_elapsed_ns = monotonic_ns() - open_start_ns;
    if (IS_ERR(file)) {
        printk("blk-read-bench: file=%s open_failed=%d\n",
               FILE_BENCH_PATH, PTR_ERR(file));
        return;
    }

    npages = (FILE_BENCH_BUFFER_SIZE + PAGE_SIZE - 1) / PAGE_SIZE;
    buffer = page_alloc(npages);
    if (!buffer) {
        printk("blk-read-bench: file=%s buffer_alloc_failed\n",
               FILE_BENCH_PATH);
        filp_close(file);
        return;
    }

    ret = file_read_pass(file, buffer, FILE_BENCH_BUFFER_SIZE,
                         &bytes, &cold_elapsed_ns);
    if (ret < 0) {
        printk("blk-read-bench: file=%s cold_read_failed=%d\n",
               FILE_BENCH_PATH, ret);
        goto out;
    }

    if (cold_elapsed_ns == 0)
        cold_elapsed_ns = 1;
    kib_per_sec = bytes * NSEC_PER_SEC / cold_elapsed_ns / 1024ULL;
    printk("blk-read-bench: file=%s mode=cold open_us=%lu bytes=%lu "
           "read_us=%lu KiB_s=%lu\n",
           FILE_BENCH_PATH,
           (unsigned long)(open_elapsed_ns / 1000ULL),
           (unsigned long)bytes,
           (unsigned long)(cold_elapsed_ns / 1000ULL),
           (unsigned long)kib_per_sec);

    for (u32 request_index = 0;
         request_index < sizeof(hot_request_sizes) /
                         sizeof(hot_request_sizes[0]);
         request_index++) {
        size_t request_size = hot_request_sizes[request_index];
        u64 hot_total_ns = 0;

        for (u32 round = 0; round < FILE_BENCH_HOT_ROUNDS; round++) {
            u64 elapsed_ns;
            u64 round_bytes;

            ret = file_read_pass(file, buffer, request_size,
                                 &round_bytes, &elapsed_ns);
            if (ret < 0 || round_bytes != bytes)
                goto out;
            hot_total_ns += elapsed_ns;
        }

        if (hot_total_ns == 0)
            hot_total_ns = 1;
        kib_per_sec = bytes * FILE_BENCH_HOT_ROUNDS * NSEC_PER_SEC;
        kib_per_sec /= hot_total_ns;
        kib_per_sec /= 1024ULL;
        printk("blk-read-bench: file=%s mode=hot request=%lu rounds=%u "
               "bytes_per_round=%lu avg_us=%lu avg_KiB_s=%lu\n",
               FILE_BENCH_PATH, (unsigned long)request_size,
               FILE_BENCH_HOT_ROUNDS, (unsigned long)bytes,
               (unsigned long)(hot_total_ns / FILE_BENCH_HOT_ROUNDS /
                               1000ULL),
               (unsigned long)kib_per_sec);
    }

out:
    page_free(buffer);
    filp_close(file);
}

static int blk_read_bench_init(void)
{
    static const size_t request_sizes[] = {
        SECTOR_SIZE,
        1024U,
        PAGE_SIZE,
        64U * 1024U,
    };
    int ret;

    printk("blk-read-bench: generated by OpenAI Codex; device=%s "
           "bytes_per_round=%u rounds=%u (read-only)\n",
           BLK_BENCH_DEVICE, BLK_BENCH_TOTAL_BYTES, BLK_BENCH_ROUNDS);

    for (size_t i = 0; i < sizeof(request_sizes) / sizeof(request_sizes[0]); i++) {
        ret = blk_read_bench_run(BLK_BENCH_DEVICE, request_sizes[i],
                                 BLK_BENCH_TOTAL_BYTES);
        if (ret < 0) {
            printk("blk-read-bench: request=%lu failed: %d\n",
                   (unsigned long)request_sizes[i], ret);
            return ret;
        }
    }

    file_read_bench();

    return 0;
}

late_initcall(blk_read_bench_init);
